import { logger } from '@clickflash/logger';
/**
 * Metadata Utilities
 * 
 * Helper functions for extracting and displaying photo metadata/EXIF data.
 */

import { PhotoMetadata } from '../types';

/**
 * Extract metadata from an image file
 */
export const extractMetadata = async (imageUrl: string): Promise<PhotoMetadata | null> => {
    try {
        // Load image to get dimensions
        const img = new Image();
        img.crossOrigin = 'anonymous';
        
        return new Promise((resolve) => {
            img.onload = () => {
                const metadata: PhotoMetadata = {
                    dimensions: {
                        width: img.naturalWidth,
                        height: img.naturalHeight,
                    },
                };
                resolve(metadata);
            };
            
            img.onerror = () => {
                resolve(null);
            };
            
            img.src = imageUrl;
        });
    } catch (error) {
        logger.error('Error extracting metadata:', error);
        return null;
    }
};

/**
 * Format file size in human-readable format
 */
export const formatFileSize = (bytes?: number): string => {
    if (!bytes) return 'Unknown';
    
    if (bytes === 0) return '0 Bytes';
    
    const k = 1024;
    const sizes = ['Bytes', 'KB', 'MB', 'GB'];
    const i = Math.floor(Math.log(bytes) / Math.log(k));
    
    return Math.round(bytes / Math.pow(k, i) * 100) / 100 + ' ' + sizes[i];
};

/**
 * Format date in readable format
 */
export const formatDate = (dateString?: string): string => {
    if (!dateString) return 'Unknown';
    
    try {
        const date = new Date(dateString);
        return date.toLocaleDateString('en-US', {
            year: 'numeric',
            month: 'long',
            day: 'numeric',
        });
    } catch (error) {
        return dateString;
    }
};

/**
 * Get image file size from URL (if possible)
 */
export const getImageFileSize = async (imageUrl: string): Promise<number | null> => {
    try {
        const response = await fetch(imageUrl, { method: 'HEAD' });
        const contentLength = response.headers.get('content-length');
        return contentLength ? parseInt(contentLength, 10) : null;
    } catch (error) {
        logger.error('Error getting file size:', error);
        return null;
    }
};

/**
 * Format metadata for display
 */
export const formatMetadataForDisplay = (metadata: PhotoMetadata | undefined): string[] => {
    if (!metadata) return [];
    
    const lines: string[] = [];
    
    if (metadata.camera) {
        lines.push(`Camera: ${metadata.camera}`);
    }
    
    if (metadata.lens) {
        lines.push(`Lens: ${metadata.lens}`);
    }
    
    if (metadata.iso) {
        lines.push(`ISO: ${metadata.iso}`);
    }
    
    if (metadata.aperture) {
        lines.push(`Aperture: f/${metadata.aperture}`);
    }
    
    if (metadata.shutterSpeed) {
        lines.push(`Shutter Speed: ${metadata.shutterSpeed}`);
    }
    
    if (metadata.focalLength) {
        lines.push(`Focal Length: ${metadata.focalLength}mm`);
    }
    
    if (metadata.dimensions) {
        lines.push(`Dimensions: ${metadata.dimensions.width} ├ù ${metadata.dimensions.height}`);
    }
    
    if (metadata.fileSize) {
        lines.push(`File Size: ${formatFileSize(metadata.fileSize)}`);
    }
    
    if (metadata.dateTaken) {
        lines.push(`Date Taken: ${formatDate(metadata.dateTaken)}`);
    }
    
    return lines;
};

import { logger } from '@clickflash/logger';
/**
 * Share Utilities
 * 
 * Helper functions for sharing photos and galleries via social media,
 * email, and copy-to-clipboard functionality.
 */

export interface ShareOptions {
    url: string;
    title?: string;
    description?: string;
    imageUrl?: string;
}

/**
 * Share to Facebook
 */
export const shareToFacebook = (options: ShareOptions): void => {
    const { url, title, description } = options;
    const shareUrl = `https://www.facebook.com/sharer/sharer.php?u=${encodeURIComponent(url)}${title ? `&quote=${encodeURIComponent(title)}` : ''}${description ? `&description=${encodeURIComponent(description)}` : ''}`;
    window.open(shareUrl, '_blank', 'width=600,height=400');
};

/**
 * Share to Twitter
 */
export const shareToTwitter = (options: ShareOptions): void => {
    const { url, title } = options;
    const text = title || 'Check out this photo!';
    const shareUrl = `https://twitter.com/intent/tweet?url=${encodeURIComponent(url)}&text=${encodeURIComponent(text)}`;
    window.open(shareUrl, '_blank', 'width=600,height=400');
};

/**
 * Share to Instagram
 * Note: Instagram doesn't support direct URL sharing, so we copy the image URL
 */
export const shareToInstagram = (imageUrl: string): void => {
    // Instagram requires the app, so we copy the image URL to clipboard
    copyToClipboard(imageUrl);
    alert('Image URL copied to clipboard! Open Instagram and paste it when creating a new post.');
};

/**
 * Share to Pinterest
 */
export const shareToPinterest = (options: ShareOptions): void => {
    const { url, title, imageUrl, description } = options;
    const shareUrl = `https://pinterest.com/pin/create/button/?url=${encodeURIComponent(url)}${imageUrl ? `&media=${encodeURIComponent(imageUrl)}` : ''}${title ? `&description=${encodeURIComponent(title)}` : ''}${description ? `&description=${encodeURIComponent(description)}` : ''}`;
    window.open(shareUrl, '_blank', 'width=600,height=400');
};

/**
 * Share via Email
 */
export const shareViaEmail = (options: ShareOptions): void => {
    const { url, title, description } = options;
    const subject = title || 'Check out this photo gallery!';
    const body = `${description || 'I wanted to share this photo gallery with you.'}\n\n${url}`;
    const mailtoUrl = `mailto:?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`;
    window.location.href = mailtoUrl;
};

/**
 * Copy URL to clipboard
 */
export const copyToClipboard = async (text: string): Promise<boolean> => {
    try {
        if (navigator.clipboard && navigator.clipboard.writeText) {
            await navigator.clipboard.writeText(text);
            return true;
        } else {
            // Fallback for older browsers
            const textArea = document.createElement('textarea');
            textArea.value = text;
            textArea.style.position = 'fixed';
            textArea.style.left = '-999999px';
            document.body.appendChild(textArea);
            textArea.select();
            const success = document.execCommand('copy');
            document.body.removeChild(textArea);
            return success;
        }
    } catch (error) {
        logger.error('Failed to copy to clipboard:', error);
        return false;
    }
};

/**
 * Generate shareable gallery URL
 */
export const generateShareableUrl = (galleryId: string, photoId?: string): string => {
    const baseUrl = window.location.origin + window.location.pathname;
    const params = new URLSearchParams();
    params.set('gallery', galleryId);
    if (photoId) {
        params.set('photo', photoId);
    }
    return `${baseUrl}?${params.toString()}`;
};

/**
 * Share photo to all platforms
 */
export const sharePhoto = (photoUrl: string, photoTitle: string, galleryUrl: string): void => {
    const options: ShareOptions = {
        url: galleryUrl,
        title: photoTitle,
        description: `Check out this photo: ${photoTitle}`,
        imageUrl: photoUrl,
    };

    // Try native Web Share API first (mobile devices)
    if (navigator.share) {
        navigator.share({
            title: photoTitle,
            text: `Check out this photo: ${photoTitle}`,
            url: galleryUrl,
        }).catch((error) => {
            logger.info('Error sharing:', error);
        });
    } else {
        // Fallback: show share options
        // This will be handled by the ShareModal component
    }
};

/**
 * Style Utilities
 * 
 * Converts ManualEdits metadata into CSS filters and transforms.
 * Enables the "Ready-Edited" view in the Online Gallery.
 * Ported from Master App (v5.0).
 */

import { ManualEdits } from '../types';

export const INITIAL_EDITS: ManualEdits = {
    exposure: 0,
    contrast: 0,
    highlights: 0,
    shadows: 0,
    saturate: 0,
    vibrance: 0,
    grayscale: 0,
    sepia: 0,
    invert: 0,
    hueRotate: 0,
    temperature: 0,
    tint: 0,
    whites: 0,
    blacks: 0,
    soften: 0,
    rotate: 0,
    straighten: 0,
    perspectiveX: 0,
    perspectiveY: 0,
    clarity: 0,
    dropShadow: 0,
    vignette: 0
};

export const getPhotoStyle = (edits: ManualEdits) => {
    // Default values fallback
    const {
        exposure = 0, contrast = 0, highlights = 0, shadows = 0,
        saturate = 0, vibrance = 0, grayscale = 0, sepia = 0, invert = 0,
        hueRotate = 0, temperature = 0, tint = 0, whites = 0, blacks = 0,
        soften = 0, rotate = 0, straighten = 0, perspectiveX = 0, perspectiveY = 0,
        clarity = 0, dropShadow = 0, vignette = 0
    } = edits;

    // Calculate brightness with whites/blacks adjustments
    const whitesAdjust = whites / 200;
    const blacksAdjust = blacks / 200;
    const brightness = 1 + (exposure / 100) + (highlights / 200) + (shadows / 400) + whitesAdjust - blacksAdjust;
    const contrastVal = 1 + (contrast / 100) + (highlights / 500) - (shadows / 500) + (clarity / 200);

    // Vibrance affects less-saturated colors more than saturation
    const vibranceAmount = vibrance / 100;
    const saturateAmount = 1 + saturate / 100;
    const combinedSaturate = vibranceAmount !== 0
        ? saturateAmount + (vibranceAmount > 0 ? vibranceAmount * 0.5 : vibranceAmount * 0.25)
        : saturateAmount;

    const filters = [
        `brightness(${brightness})`,
        `contrast(${contrastVal})`,
        `saturate(${combinedSaturate})`,
    ];

    // Apply temperature and tint using sepia for now (or color matrix if available in future)
    if (temperature !== 0) {
        filters.push(`sepia(${Math.abs(temperature) * 0.5}%)`);
    }

    filters.push(
        `grayscale(${grayscale}%)`,
        `sepia(${sepia}%)`,
        `invert(${invert}%)`,
        `hue-rotate(${hueRotate}deg)`,
        `blur(${soften}px)`,
    );

    if (dropShadow > 0) {
        filters.push(`drop-shadow(0 4px ${dropShadow}px rgba(0,0,0,0.5))`);
    }

    // Calculate scale-to-fit for straighten to prevent edge cropping
    const angle = rotate + straighten;
    let transformStr = '';

    if (straighten !== 0) {
        const rad = Math.abs(straighten * Math.PI / 180);
        const cos = Math.abs(Math.cos(rad));
        const sin = Math.abs(Math.sin(rad));
        const scale = 1 / (cos + sin);
        transformStr = `rotate(${angle}deg) scale(${scale})`;
    } else if (rotate !== 0) {
        transformStr = `rotate(${angle}deg)`;
    }

    // Add perspective correction
    const perspectiveParts: string[] = [];
    if (perspectiveX !== 0 || perspectiveY !== 0) {
        const perspectiveValue = 1000 + Math.abs(perspectiveX) * 10;
        const rotateX = perspectiveY * 0.1;
        const rotateY = perspectiveX * 0.1;
        if (rotateY !== 0) perspectiveParts.push(`perspective(${perspectiveValue}px)`);
        if (rotateX !== 0 || rotateY !== 0) {
            perspectiveParts.push(`rotateX(${rotateX}deg)`);
            perspectiveParts.push(`rotateY(${rotateY}deg)`);
        }
    }

    if (perspectiveParts.length > 0) {
        transformStr = perspectiveParts.join(' ') + (transformStr ? ' ' + transformStr : '');
    } else if (!transformStr) {
        transformStr = 'none';
    }

    // Note: Vignette creates an overlay, here we just return style props.
    // Ideally vignette is handled by a separate element overlay to prevent layout issues.

    return {
        filter: filters.join(' '),
        transform: transformStr,
        transition: 'filter 0.2s ease-out, transform 0.2s ease-out'
    };
};

